export type ParsedJoinGameInstruction<
  TProgram extends string = typeof TIMBA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    game: TAccountMetas[0];
    player: TAccountMetas[1];
    oracleOperator?: TAccountMetas[2] | undefined;
    tokenMint: TAccountMetas[3];
    gameToken: TAccountMetas[4];
    gameVault: TAccountMetas[5];
    gameTokenAccount: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
    associatedTokenProgram: TAccountMetas[8];
    playerTokenAccount: TAccountMetas[9];
    oracle: TAccountMetas[10];
  };
  data: JoinGameInstructionData;
};

export function parseJoinGameInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedJoinGameInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === TIMBA_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      game: getNextAccount(),
      player: getNextAccount(),
      oracleOperator: getNextOptionalAccount(),
      tokenMint: getNextAccount(),
      gameToken: getNextAccount(),
      gameVault: getNextAccount(),
      gameTokenAccount: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      playerTokenAccount: getNextAccount(),
      oracle: getNextAccount(),
    },
    data: getJoinGameInstructionDataDecoder().decode(instruction.data),
  };
}
